CREATE TABLE website_analyses (id INTEGER PRIMARY KEY CHECK (typeof(id) = 'integer' AND id > 0), evidence_id INTEGER NOT NULL CHECK (typeof(evidence_id) = 'integer' AND evidence_id > 0), lead_id TEXT NOT NULL CHECK (length(trim(lead_id)) > 0), lead_version INTEGER NOT NULL CHECK (typeof(lead_version) = 'integer' AND lead_version > 0), summary TEXT NOT NULL CHECK (length(summary) BETWEEN 1 AND 800 AND summary = trim(summary)), findings_json TEXT NOT NULL CHECK (length(findings_json) > 0), provider TEXT NOT NULL CHECK (provider = 'gemini'), model TEXT NOT NULL CHECK (model IN ('gemini-3.8-flash', 'gemini-3.6-flash', 'gemini-3.5-flash-lite', 'gemini-3.1-flash-lite')), attempted_models_json TEXT NOT NULL CHECK (length(attempted_models_json) > 0), stored_at TEXT NOT NULL CHECK (length(stored_at) = 24 AND substr(stored_at, 1, 4) GLOB '[0-9][0-9][0-9][0-9]' AND substr(stored_at, 5, 1) = '-' AND substr(stored_at, 6, 2) GLOB '[0-9][0-9]' AND substr(stored_at, 8, 1) = '-' AND substr(stored_at, 9, 2) GLOB '[0-9][0-9]' AND substr(stored_at, 11, 1) = 'T' AND substr(stored_at, 12, 2) GLOB '[0-9][0-9]' AND substr(stored_at, 14, 1) = ':' AND substr(stored_at, 15, 2) GLOB '[0-9][0-9]' AND substr(stored_at, 17, 1) = ':' AND substr(stored_at, 18, 2) GLOB '[0-9][0-9]' AND substr(stored_at, 20, 1) = '.' AND substr(stored_at, 21, 3) GLOB '[0-9][0-9][0-9]' AND substr(stored_at, 24, 1) = 'Z' AND CAST(substr(stored_at, 6, 2) AS INTEGER) BETWEEN 1 AND 12 AND CAST(substr(stored_at, 9, 2) AS INTEGER) BETWEEN 1 AND 31 AND CAST(substr(stored_at, 12, 2) AS INTEGER) BETWEEN 0 AND 23 AND CAST(substr(stored_at, 15, 2) AS INTEGER) BETWEEN 0 AND 59 AND CAST(substr(stored_at, 18, 2) AS INTEGER) BETWEEN 0 AND 59 AND date(substr(stored_at, 1, 10)) = substr(stored_at, 1, 10) AND strftime('%Y-%m-%dT%H:%M:%fZ', stored_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%fZ', stored_at) = stored_at), FOREIGN KEY (evidence_id) REFERENCES single_page_crawl_evidence(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TRIGGER website_analyses_prevent_update BEFORE UPDATE ON website_analyses BEGIN SELECT RAISE(ABORT, 'website_analyses is append-only'); END;
CREATE TRIGGER website_analyses_prevent_delete BEFORE DELETE ON website_analyses BEGIN SELECT RAISE(ABORT, 'website_analyses is append-only'); END;
